<section class="ds-panel"><div class="ds-panel-head"><div><h2><?php esc_html_e( 'Weekly calendar', 'digital-signage' ); ?></h2><p><?php esc_html_e( 'Content schedules and controller sleep periods in one view.', 'digital-signage' ); ?></p></div><button class="ds-button primary" data-open="schedule-dialog"><?php esc_html_e( 'New content schedule', 'digital-signage' ); ?></button></div><div class="ds-calendar"><?php foreach ( $day_names as $day_key => $day_label ) : ?><div class="ds-day"><strong><?php echo esc_html( $day_label ); ?></strong><?php foreach ( $schedules as $schedule ) : $days = (array) get_post_meta( $schedule->ID, 'ds_days', true ); if ( ! in_array( $day_key, $days, true ) ) { continue; } ?><article><b><?php echo esc_html( $schedule->post_title ); ?></b><span><?php echo esc_html( get_post_meta( $schedule->ID, 'ds_start_time', true ) . '–' . get_post_meta( $schedule->ID, 'ds_end_time', true ) ); ?></span><button class="ds-icon danger" data-delete-type="schedule" data-delete-id="<?php echo absint( $schedule->ID ); ?>">×</button></article><?php endforeach; ?><?php foreach ( $controllers as $item ) : $sleep = json_decode( (string) $item->power_schedule, true ); $day_number = array_search( $day_key, array_keys( $day_names ), true ); if ( empty( $sleep['enabled'] ) || ! in_array( $day_number, array_map( 'absint', $sleep['days'] ?? array() ), true ) ) { continue; } ?><article class="sleep"><b><?php echo esc_html( $item->name ?: $item->hostname ); ?></b><span><?php echo esc_html( ( $sleep['sleep_time'] ?? '22:00' ) . '–' . ( $sleep['wake_time'] ?? '07:00' ) . ' · screens off' ); ?></span></article><?php endforeach; ?></div><?php endforeach; ?></div></section>
<section class="ds-panel"><h3><?php esc_html_e( 'Display sleep schedules', 'digital-signage' ); ?></h3><p><?php echo esc_html( sprintf( __( 'All times use the WordPress server clock (%s) and the 24-hour HH:MM format.', 'digital-signage' ), wp_timezone_string() ?: 'UTC' ) ); ?></p><div class="ds-sleep-list"><?php foreach ( $controllers as $item ) : $sleep = json_decode( (string) $item->power_schedule, true ) ?: array(); $sleep_days = array_map( 'absint', (array) ( $sleep['days'] ?? range( 0, 6 ) ) ); ?><form method="post" action="<?php echo esc_url( $action_url ); ?>"><?php wp_nonce_field( 'ds_portal_action' ); ?><input type="hidden" name="action" value="ds_portal_action"><input type="hidden" name="operation" value="save_sleep_schedule"><input type="hidden" name="group_id" value="<?php echo absint( $group_id ); ?>"><input type="hidden" name="controller_id" value="<?php echo absint( $item->id ); ?>"><strong><?php echo esc_html( $item->name ?: $item->hostname ); ?></strong><label><input type="checkbox" name="enabled" value="1" <?php checked( ! empty( $sleep['enabled'] ) ); ?>> <?php esc_html_e( 'Enabled', 'digital-signage' ); ?></label><label><?php esc_html_e( 'On', 'digital-signage' ); ?><input class="ds-time" name="wake_time" value="<?php echo esc_attr( $sleep['wake_time'] ?? '07:00' ); ?>" pattern="(?:[01][0-9]|2[0-3]):[0-5][0-9]" placeholder="07:00" required></label><label><?php esc_html_e( 'Off', 'digital-signage' ); ?><input class="ds-time" name="sleep_time" value="<?php echo esc_attr( $sleep['sleep_time'] ?? '22:00' ); ?>" pattern="(?:[01][0-9]|2[0-3]):[0-5][0-9]" placeholder="22:00" required></label><div class="ds-day-picks" aria-label="<?php esc_attr_e( 'Active weekdays', 'digital-signage' ); ?>"><?php foreach ( $day_names as $day_key => $day_label ) : $day_number = array_search( $day_key, array_keys( $day_names ), true ); ?><label><input type="checkbox" name="days[]" value="<?php echo absint( $day_number ); ?>" <?php checked( in_array( $day_number, $sleep_days, true ) ); ?>><?php echo esc_html( mb_substr( $day_label, 0, 2 ) ); ?></label><?php endforeach; ?></div><span><?php echo esc_html( wp_timezone_string() ?: 'UTC' ); ?></span><button class="ds-button"><?php esc_html_e( 'Save schedule', 'digital-signage' ); ?></button></form><?php endforeach; ?></div></section>

<?php elseif ( 'media' === $section ) : $media = array_values( array_filter( get_posts( array( 'post_type' => 'attachment', 'post_status' => 'inherit', 'posts_per_page' => 100, 'orderby' => 'date', 'order' => 'DESC' ) ), array( 'DS_Groups', 'can_access_post' ) ) ); ?><section class="ds-panel"><div class="ds-panel-head"><div><h2><?php esc_html_e( 'Group media', 'digital-signage' ); ?></h2><p><?php esc_html_e( 'Files uploaded here are visible only inside this group.', 'digital-signage' ); ?></p></div><form class="ds-upload" method="post" enctype="multipart/form-data" action="<?php echo esc_url( $action_url ); ?>"><?php wp_nonce_field( 'ds_portal_action' ); ?><input type="hidden" name="action" value="ds_portal_action"><input type="hidden" name="operation" value="upload_media"><input type="hidden" name="group_id" value="<?php echo absint( $group_id ); ?>"><input type="file" name="media_file" required><button class="ds-button primary"><?php esc_html_e( 'Upload', 'digital-signage' ); ?></button></form></div><div class="ds-media-grid"><?php foreach ( $media as $item ) : ?><figure><?php echo wp_get_attachment_image( $item->ID, 'medium' ); ?><figcaption><?php echo esc_html( $item->post_title ); ?><button class="ds-copy" data-copy="<?php echo esc_attr( wp_get_attachment_url( $item->ID ) ); ?>"><?php esc_html_e( 'Copy URL', 'digital-signage' ); ?></button></figcaption></figure><?php endforeach; ?></div></section>

<?php elseif ( 'people' === $section ) : ?><section class="ds-panel"><div class="ds-panel-head"><div><h2><?php esc_html_e( 'Group members', 'digital-signage' ); ?></h2><p><?php esc_html_e( 'Members see this group’s screens, controllers, channels, schedules, settings, and media.', 'digital-signage' ); ?></p></div></div><form class="ds-add-person" method="post" action="<?php echo esc_url( $action_url ); ?>"><?php wp_nonce_field( 'ds_portal_action' ); ?><input type="hidden" name="action" value="ds_portal_action"><input type="hidden" name="operation" value="member"><input type="hidden" name="group_id" value="<?php echo absint( $group_id ); ?>"><input type="email" name="email" placeholder="person@example.com" required><input type="hidden" name="member_action" value="add"><button class="ds-button primary"><?php esc_html_e( 'Add person', 'digital-signage' ); ?></button></form><div class="ds-list"><?php foreach ( get_users() as $member ) : if ( ! in_array( $group_id, DS_Groups::user_group_ids( $member->ID ), true ) ) { continue; } ?><div class="ds-row"><div><strong><?php echo esc_html( $member->display_name ); ?></strong><small><?php echo esc_html( $member->user_email ); ?> · <?php esc_html_e( 'Screen Manager', 'digital-signage' ); ?></small></div><?php if ( $member->ID !== get_current_user_id() ) : ?><form method="post" action="<?php echo esc_url( $action_url ); ?>"><?php wp_nonce_field( 'ds_portal_action' ); ?><input type="hidden" name="action" value="ds_portal_action"><input type="hidden" name="operation" value="member"><input type="hidden" name="group_id" value="<?php echo absint( $group_id ); ?>"><input type="hidden" name="email" value="<?php echo esc_attr( $member->user_email ); ?>"><button class="ds-button" name="member_action" value="remove"><?php esc_html_e( 'Remove', 'digital-signage' ); ?></button></form><?php endif; ?></div><?php endforeach; ?></div></section>

<?php elseif ( 'settings' === $section ) : $settings = DS_Groups::settings( $group_id ); ?><section class="ds-panel"><div class="ds-panel-head"><div><h2><?php esc_html_e( 'Group settings', 'digital-signage' ); ?></h2><p><?php esc_html_e( 'Playback defaults for this group only.', 'digital-signage' ); ?></p></div></div><?php if ( ! $group_id && current_user_can( 'manage_options' ) ) : ?><p class="ds-empty"><?php esc_html_e( 'Create a group before saving group settings.', 'digital-signage' ); ?></p><?php else : ?><form class="ds-form ds-form-wide" method="post" action="<?php echo esc_url( $action_url ); ?>"><?php wp_nonce_field( 'ds_portal_action' ); ?><input type="hidden" name="action" value="ds_portal_action"><input type="hidden" name="operation" value="save_settings"><input type="hidden" name="group_id" value="<?php echo absint( $group_id ); ?>"><label><?php esc_html_e( 'Image duration (seconds)', 'digital-signage' ); ?><input type="number" min="1" name="ds_settings[duration_image]" value="<?php echo absint( $settings['duration_image'] ); ?>"></label><label><?php esc_html_e( 'Video fallback duration', 'digital-signage' ); ?><input type="number" min="1" name="ds_settings[duration_video]" value="<?php echo absint( $settings['duration_video'] ); ?>"></label><label><?php esc_html_e( 'Update interval', 'digital-signage' ); ?><input type="number" min="5" name="ds_settings[poll_interval]" value="<?php echo absint( $settings['poll_interval'] ); ?>"></label><label><?php esc_html_e( 'Timezone', 'digital-signage' ); ?><input name="ds_settings[timezone]" value="<?php echo esc_attr( $settings['timezone'] ); ?>"></label><label><?php esc_html_e( 'Transition', 'digital-signage' ); ?><select name="ds_settings[transition]"><option value="fade">Fade</option><option value="none">None</option><option value="slide">Slide</option><option value="zoom">Zoom</option></select></label><button class="ds-button primary"><?php esc_html_e( 'Save settings', 'digital-signage' ); ?></button></form><?php endif; ?><?php if ( current_user_can( 'manage_options' ) ) : ?><hr><form class="ds-add-person" method="post" action="<?php echo esc_url( $action_url ); ?>"><?php wp_nonce_field( 'ds_portal_action' ); ?><input type="hidden" name="action" value="ds_portal_action"><input type="hidden" name="operation" value="create_group"><input name="name" placeholder="<?php esc_attr_e( 'New group name', 'digital-signage' ); ?>" required><button class="ds-button"><?php esc_html_e( 'Create group', 'digital-signage' ); ?></button></form><?php endif; ?></section>

